"""Per-problem archive manifest (generated by scripts/make_manifest.py).

The manifest pins, for each problem at the dataset revisions in
biomysterybench.py, the archive holding its data, the archive's size and LFS
sha256, a size tier and whether a human solved the problem. Staging verifies
every download against it, so a change on the dataset side fails loudly instead
of quietly changing what the agent sees.
"""

import json
from dataclasses import dataclass
from functools import cache
from pathlib import Path
from typing import Any

MANIFEST_PATH = Path(__file__).parent / "manifest.json"

# The preview set ships every problem in one bundle, under <id>/.
PREVIEW_ARCHIVE = "data.zip"

# (tier, exclusive upper bound in bytes). The last tier has no upper bound.
TIER_BOUNDS: list[tuple[str, int | None]] = [
    ("small", 2_000_000_000),
    ("medium", 10_000_000_000),
    ("large", None),
]
TIERS = tuple(name for name, _ in TIER_BOUNDS)


@dataclass(frozen=True)
class ProblemArchive:
    """Where a problem's data lives on HuggingFace, and how to check it."""

    problem_id: str
    repo: str
    revision: str
    archive: str
    size: int
    sha256: str
    tier: str
    human_solvable: bool

    @property
    def bundled(self) -> bool:
        """Whether the archive bundles every problem under <id>/ (the preview set)."""
        return self.archive == PREVIEW_ARCHIVE


@cache
def _load() -> dict[str, Any]:
    return json.loads(MANIFEST_PATH.read_text())


def load_source(source: str, repo: str, revision: str) -> dict[str, ProblemArchive]:
    """Return problem id -> archive for `source`, checked against the pinned revision."""
    entry = _load()["sources"][source]
    if (entry["repo"], entry["revision"]) != (repo, revision):
        raise ValueError(
            f"manifest.json is for {entry['repo']}@{entry['revision']} but the task "
            f"pins {repo}@{revision}; regenerate it with scripts/make_manifest.py"
        )
    return {
        pid: ProblemArchive(problem_id=pid, repo=repo, revision=revision, **fields)
        for pid, fields in entry["problems"].items()
    }
